package com.example.arcana.client;
import com.example.arcana.network.*; import net.minecraft.client.gui.GuiGraphics; import net.minecraft.client.gui.components.Button; import net.minecraft.client.gui.screens.Screen; import net.minecraft.network.chat.Component;
public class SkillTreeScreen extends Screen { public SkillTreeScreen(){super(Component.literal("Arcana Skill Tree"));} protected void init(){addRenderableWidget(Button.builder(Component.literal("Upgrade Arcane Bolt Range"),b->ArcanaNetwork.CHANNEL.sendToServer(new UpgradeSkillPacket("bolt_range"))).bounds(width/2-100,height/2-10,200,20).build());} public void render(GuiGraphics g,int mx,int my,float pt){renderBackground(g);g.drawCenteredString(font,title,width/2,30,0xE8D5FF);g.drawCenteredString(font,"Each upgrade adds 8 blocks of range",width/2,60,0xFFFFFF);super.render(g,mx,my,pt);}}
